# Определяем структуру дома как граф
house = {
    "Домашний спортзал": {"юг": "Солнечная комната"},
    "Солнечная комната": {"север": "Домашний спортзал", "юг": "Тренировочная"},
    "Тренировочная": {"север": "Солнечная комната", "запад": "Библиотека"},
    "Библиотека": {"восток": "Тренировочная"}
}

visited_rooms = set()
path = []

def dfs_traversal(current_room):
    visited_rooms.add(current_room)
    path.append(current_room)

    for direction, neighbor in house[current_room].items():
        if neighbor not in visited_rooms:
            print(f"ИДТИ: {direction}")
            dfs_traversal(neighbor)

    if len(visited_rooms) == len(house):
        print("ГОТОВО")
    else:
        # Если все соседние комнаты посещены, возвращаемся назад
        for direction, neighbor in house[current_room].items():
            if neighbor in path and neighbor != path[-2]:
                reverse_direction = {
                    "север": "юг",
                    "юг": "север",
                    "восток": "запад",
                    "запад": "восток"
                }
                print(f"ИДТИ: {reverse_direction[direction]}")
                dfs_traversal(neighbor)
                break

# Запускаем обход с начальной комнаты
dfs_traversal("Домашний спортзал")

